/**
 * 样式：CSS 文本 + 运行时注入。
 *
 * 为什么不用 `.css` 文件：DSH 客户端插件包由 tsdown 打成单个 JS，
 * 没有 CSS sidecar 加载通道（生态里的客户端插件一律用
 * `document.createElement('style')` 注入）。把 CSS 作为字符串放进 TS，
 * 保证它一定被打进 client bundle。
 *
 * 与此同时，关键几何（小圆圈的尺寸/颜色）在组件里用**内联样式**兜底：
 * 即使样式注入失败，控件仍然可见 —— 只有动画会缺失。
 */
/** 设计 tokens + 组件样式。 */
export declare const CONNECTION_CARD_CSS = "\n:root {\n  --ccr-rail-width: 24px;\n  --ccr-rail-lane-gap: 8px;\n  --ccr-rail-node-size: 8px;\n  --ccr-perm-read: #9CA3AF;\n  --ccr-perm-suggest: #3B82F6;\n  --ccr-perm-write: #F97316;\n  --ccr-health-green: #10B981;\n  --ccr-health-yellow: #F59E0B;\n  --ccr-health-red: #EF4444;\n  --ccr-line-color: #60A5FA;\n  /* \u62C9\u7EBF\u300C\u6C34\u6D41\u300D\u4E3B\u8272\u3002\n     \u7528\u6237\u8981\u6C42\u767D\u8272\u534A\u900F\u660E\uFF1B\u4F46\u7EAF\u767D\u5728\u6D45\u8272\u4E3B\u9898\u4E0B\u4E0D\u53EF\u89C1\uFF0C\n     \u56E0\u6B64\u53D6 DSH \u7684\u4E3B\u9898 token\uFF08\u6DF1\u8272\u4E3B\u9898=\u767D\uFF0C\u6D45\u8272\u4E3B\u9898=\u6DF1\uFF09\uFF0C\u4FDD\u8BC1\u4E24\u4E2A\u4E3B\u9898\u90FD\u770B\u5F97\u89C1\u3002\n     \u60F3\u5F3A\u5236\u7EAF\u767D\u5C31\u628A\u8FD9\u91CC\u6539\u6210 #ffffff\u3002 */\n  --ccr-flow-color: var(--dsw-alias-label-primary, #ffffff);\n  --ccr-fast: 150ms cubic-bezier(0.2, 0, 0, 1);\n  --ccr-panel-highlight: rgba(96, 165, 250, 0.12);\n}\n\n/* \u2550\u2550\u2550 AnchorCircle\uFF08\u51E0\u4F55\u5728\u5185\u8054\u6837\u5F0F\u91CC\uFF0C\u8FD9\u91CC\u53EA\u8865\u52A8\u6548\uFF09 \u2550\u2550\u2550 */\n.ccr-anchor {\n  animation: none;\n}\n\n.ccr-anchor__pulse {\n  position: absolute;\n  inset: -3px;\n  border-radius: 50%;\n  border: 1.5px solid var(--ccr-flow-color);\n  opacity: 0;\n  pointer-events: none;\n}\n\n.ccr-anchor--dragging .ccr-anchor__pulse {\n  animation: ccr-anchor-pulse 1200ms ease-out infinite;\n}\n\n/* \u5E45\u5EA6\u6536\u5C0F\uFF1A1 \u2192 1.45\uFF08\u539F\u6765 2 \u592A\u5927\uFF0C\u89C2\u611F\"\u4E00\u76F4\u95EA\"\uFF09 */\n@keyframes ccr-anchor-pulse {\n  0% { transform: scale(1); opacity: 0.5; }\n  100% { transform: scale(1.45); opacity: 0; }\n}\n\n/* \u2550\u2550\u2550 DragLine\uFF1A\u6C34\u6D41\u6548\u679C \u2550\u2550\u2550\n   \u4E09\u5C42\u53E0\u52A0\uFF1A\n     1. ccr-flow__glow   \u5BBD + \u9AD8\u65AF\u6A21\u7CCA + \u6781\u4F4E\u900F\u660E \u2192 \u6C34\u6C7D\u5149\u6655\n     2. ccr-flow__core   \u6E10\u53D8\u767D\u4E3B\u7EBF\uFF08\u4E24\u7AEF\u6DE1\u51FA\uFF0C\u4E0D\u662F\u786C\u90A6\u90A6\u7684\u7EBF\uFF09\n     3. ccr-flow__band   \u77ED\u5212\u7EBF\u6CBF\u8DEF\u5F84\u6ED1\u52A8 \u2192 \u6C34\u5728\u6D41\n   \u7C92\u5B50\uFF08\u6C34\u73E0\uFF09\u7531\u7EC4\u4EF6\u5185\u8054\u6E32\u67D3\u3002 */\n.ccr-drag-line {\n  position: fixed;\n  inset: 0;\n  pointer-events: none;\n  z-index: 9999;\n  overflow: visible;\n}\n\n.ccr-flow__glow {\n  fill: none;\n  stroke: var(--ccr-flow-color);\n  stroke-width: 7px;\n  stroke-opacity: 0.16;\n  stroke-linecap: round;\n}\n\n.ccr-flow__core {\n  fill: none;\n  stroke-linecap: round;\n}\n\n.ccr-flow__band {\n  fill: none;\n  stroke: var(--ccr-flow-color);\n  stroke-width: 1.2px;\n  stroke-opacity: 0.5;\n  stroke-linecap: round;\n  stroke-dasharray: 34 58;\n  animation: ccr-water-flow 1100ms linear infinite;\n}\n\n@keyframes ccr-water-flow {\n  to { stroke-dashoffset: -92; }\n}\n\n.ccr-flow__particle {\n  fill: var(--ccr-flow-color);\n}\n\n/* \u2550\u2550\u2550 SessionRail\uFF1A\u4F1A\u8BDD\u884C\u4E0A\u7684\u7AD6\u7EBF\uFF08\u98CE\u683C\u5BF9\u9F50\u62D6\u62FD\u7684\u6C34\u6D41\u7EBF\uFF09 \u2550\u2550\u2550 */\n.ccr-rail__flow {\n  animation: ccr-rail-flow 2600ms linear infinite;\n}\n\n@keyframes ccr-rail-flow {\n  to { stroke-dashoffset: -36; }\n}\n\n/* \u2550\u2550\u2550 SessionRail \u2550\u2550\u2550 */\n.ccr-rail {\n  position: relative;\n  flex-shrink: 0;\n  height: 100%;\n  overflow: hidden;\n}\n\n.ccr-rail__overflow {\n  position: absolute;\n  bottom: 8px;\n  left: 0;\n  right: 0;\n  text-align: center;\n  font-size: 10px;\n  opacity: 0.6;\n}\n\n/* \u2550\u2550\u2550 RailLane \u2550\u2550\u2550 */\n.ccr-lane {\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  pointer-events: none;\n}\n\n.ccr-lane__line {\n  stroke-linecap: round;\n  transition: stroke-width var(--ccr-fast), opacity var(--ccr-fast);\n}\n\n.ccr-lane__line--dimmed { opacity: 0.2; }\n\n/* \u2550\u2550\u2550 \u62D6\u62FD\u843D\u70B9\u63D0\u793A\uFF08\u547D\u4E2D\u5DE6\u4FA7\u4F1A\u8BDD\u884C\uFF09 \u2550\u2550\u2550 */\n.ccr-target {\n  background: var(--ccr-panel-highlight) !important;\n  box-shadow: inset 2px 0 0 var(--ccr-flow-color) !important;\n}\n\n/* \u5DF2\u8FDE\u7684\u76EE\u6807\uFF1A\u677E\u624B\u4F1A\u65AD\u5F00\uFF0C\u7528\u7EA2\u8C03\u533A\u5206\u4E8E\u300C\u4F1A\u8FDE\u63A5\u300D */\n.ccr-target--disconnect {\n  background: rgba(239, 68, 68, 0.13) !important;\n  box-shadow: inset 2px 0 0 #EF4444 !important;\n}\n\n/* \u2550\u2550\u2550 \u9762\u677F\uFF08main \u69FD\u4F4D\uFF0C\u6574\u9875\u5BBD\u5EA6\uFF09 \u2550\u2550\u2550 */\n.ccr-page {\n  box-sizing: border-box;\n  width: 100%;\n  max-width: 720px;\n  margin: 0 auto;\n  padding: 24px 20px 40px;\n  color: var(--dsw-alias-label-primary, inherit);\n  font-size: 13px;\n}\n\n.ccr-page__head { margin-bottom: 20px; }\n\n.ccr-page__title {\n  margin: 0 0 6px;\n  font-size: 17px;\n  font-weight: 600;\n}\n\n.ccr-page__sub {\n  margin: 0;\n  font-size: 12px;\n  line-height: 1.6;\n  color: var(--dsw-alias-label-secondary, #888);\n}\n\n.ccr-block {\n  margin-bottom: 22px;\n  padding: 14px 16px;\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.25));\n  border-radius: 10px;\n}\n\n.ccr-block__title {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin: 0 0 12px;\n  font-size: 13px;\n  font-weight: 600;\n}\n\n.ccr-count {\n  padding: 0 6px;\n  border-radius: 8px;\n  background: var(--ccr-panel-highlight);\n  font-size: 11px;\n  font-weight: 500;\n}\n\n/* \u2500\u2500\u2500 \u8868\u5355 \u2500\u2500\u2500 */\n.ccr-form {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.ccr-select,\n.ccr-input {\n  flex: 1 1 160px;\n  min-width: 0;\n  box-sizing: border-box;\n  padding: 6px 8px;\n  font: inherit;\n  font-size: 12px;\n  color: inherit;\n  background: var(--dsw-alias-bg-layer-2, rgba(128,128,128,0.08));\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.3));\n  border-radius: 6px;\n}\n\n.ccr-form__sep { opacity: 0.5; }\n\n/* \u65B0\u5EFA\u8FDE\u63A5\u4E2D\u95F4\u7684\u53EF\u70B9\u8FDE\u63A5\u7B26\u3002\n   \u9ED8\u8BA4\u5916\u89C2\u4E0E\u666E\u901A \u2194 \u5206\u9694\u7B26\u4E00\u81F4\uFF08\u65E0\u6846\u3001\u65E0\u5E95\u8272\uFF09\uFF1B\n   \u60AC\u6D6E\u65F6\u51FA\u73B0\u8FB9\u6846\u4E0E\u5E95\u8272\uFF0C\u5E76\u6D6E\u51FA\u4E00\u4E2A + / \u2212 \u63D0\u793A\u53EF\u4EE5\u589E\u5220\u4E00\u4E2A\u4F1A\u8BDD\u69FD\u4F4D\u3002 */\n.ccr-form__join {\n  display: inline-flex;\n  align-items: center;\n  gap: 1px;\n  flex: none;\n  padding: 2px 5px;\n  font: inherit;\n  font-size: 12px;\n  line-height: 1;\n  color: inherit;\n  background: transparent;\n  border: 1px solid transparent;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: background 120ms ease, border-color 120ms ease;\n}\n\n.ccr-form__join-arrow { opacity: 0.5; }\n\n.ccr-form__join-mark {\n  font-size: 11px;\n  opacity: 0;\n  transform: translateX(-2px);\n  transition: opacity 120ms ease, transform 120ms ease;\n}\n\n.ccr-form__join:hover {\n  background: var(--ccr-panel-highlight);\n  border-color: var(--dsw-alias-border-l2, rgba(128, 128, 128, 0.4));\n}\n\n.ccr-form__join:hover .ccr-form__join-arrow { opacity: 0.9; }\n\n.ccr-form__join:hover .ccr-form__join-mark {\n  opacity: 1;\n  transform: translateX(0);\n}\n\n/* \u5C0F\u53F7\u5206\u6BB5\u63A7\u4EF6\uFF08\u8F68\u9053\u7EBF\u8DEF\u5F00\u5173\uFF09 */\n.ccr-seg--small .ccr-seg__item {\n  padding: 2px 8px;\n  font-size: 11px;\n}\n\n.ccr-rail-toggle { margin-left: auto; }\n\n.ccr-btn {\n  padding: 6px 14px;\n  font: inherit;\n  font-size: 12px;\n  color: inherit;\n  background: transparent;\n  border: 1px solid var(--dsw-alias-border-l2, rgba(128,128,128,0.4));\n  border-radius: 6px;\n  cursor: pointer;\n}\n\n.ccr-btn:hover:not(:disabled) { background: var(--ccr-panel-highlight); }\n.ccr-btn:disabled { opacity: 0.45; cursor: default; }\n\n.ccr-btn--primary {\n  border-color: var(--ccr-flow-color);\n  background: var(--ccr-panel-highlight);\n}\n\n.ccr-btn--danger:hover:not(:disabled) {\n  background: rgba(239, 68, 68, 0.14);\n  border-color: #EF4444;\n}\n\n.ccr-link {\n  margin-top: 8px;\n  padding: 0;\n  font: inherit;\n  font-size: 11px;\n  color: inherit;\n  opacity: 0.6;\n  background: none;\n  border: 0;\n  cursor: pointer;\n  text-decoration: underline;\n}\n\n.ccr-hint,\n.ccr-field__hint {\n  margin: 8px 0 0;\n  font-size: 11px;\n  line-height: 1.5;\n  color: var(--dsw-alias-label-secondary, #888);\n  opacity: 0.85;\n}\n\n/* \u2500\u2500\u2500 \u63D0\u793A\u6761 \u2500\u2500\u2500 */\n.ccr-notice,\n.ccr-empty,\n.ccr-error {\n  margin-bottom: 12px;\n  padding: 8px 12px;\n  border-radius: 6px;\n  font-size: 12px;\n}\n\n.ccr-notice { background: var(--ccr-panel-highlight); }\n.ccr-empty { color: var(--dsw-alias-label-secondary, #888); padding-left: 0; }\n.ccr-error { color: #EF4444; padding-left: 0; }\n\n/* \u2500\u2500\u2500 \u8FDE\u63A5\u5361\u7247 \u2500\u2500\u2500 */\n.ccr-list { display: flex; flex-direction: column; gap: 6px; }\n\n.ccr-conn {\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.25));\n  border-radius: 8px;\n  overflow: hidden;\n}\n\n.ccr-conn--open { background: var(--dsw-alias-bg-layer-1, rgba(128,128,128,0.05)); }\n\n.ccr-conn__head {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  width: 100%;\n  box-sizing: border-box;\n  padding: 10px 12px;\n  font: inherit;\n  font-size: 12px;\n  color: inherit;\n  text-align: left;\n  background: none;\n  border: 0;\n  cursor: pointer;\n}\n\n.ccr-conn__head:hover { background: var(--ccr-panel-highlight); }\n\n.ccr-dot {\n  flex: none;\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n}\n\n.ccr-conn__pair {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n}\n\n.ccr-conn__session {\n  max-width: 180px;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n}\n\n.ccr-conn__arrow { opacity: 0.45; }\n\n.ccr-conn__meta {\n  margin-left: auto;\n  flex: none;\n  font-size: 11px;\n  color: var(--dsw-alias-label-secondary, #888);\n}\n\n.ccr-chevron { flex: none; opacity: 0.45; font-size: 10px; }\n\n.ccr-conn__body {\n  padding: 4px 12px 12px;\n  border-top: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.2));\n}\n\n.ccr-field { margin: 12px 0; }\n\n.ccr-field__label {\n  margin-bottom: 6px;\n  font-size: 12px;\n  font-weight: 500;\n}\n\n.ccr-seg {\n  display: inline-flex;\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.3));\n  border-radius: 6px;\n  overflow: hidden;\n}\n\n.ccr-seg__item {\n  padding: 5px 14px;\n  font: inherit;\n  font-size: 12px;\n  color: inherit;\n  background: none;\n  border: 0;\n  border-right: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.25));\n  cursor: pointer;\n  opacity: 0.7;\n}\n\n.ccr-seg__item:last-child { border-right: 0; }\n.ccr-seg__item:hover:not(:disabled) { background: var(--ccr-panel-highlight); }\n.ccr-seg__item--active { background: var(--ccr-panel-highlight); opacity: 1; font-weight: 500; }\n.ccr-seg__item:disabled { cursor: default; opacity: 0.4; }\n\n.ccr-conn__actions { display: flex; gap: 8px; margin-top: 12px; }\n\n.ccr-card-stack { margin: 12px 0; }\n\n/* \u2550\u2550\u2550 \u5361\u7247\u533A \u2550\u2550\u2550 */\n.ccr-cards { margin: 12px 0; }\n\n.ccr-cards__head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 8px;\n}\n\n.ccr-cards__add { margin-left: auto; margin-top: 0; }\n\n.ccr-cards__picker {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  margin-bottom: 8px;\n  padding: 8px;\n  border: 1px dashed var(--dsw-alias-border-l2, rgba(128,128,128,0.4));\n  border-radius: 8px;\n}\n\n.ccr-card-option {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 2px;\n  padding: 8px 10px;\n  font: inherit;\n  color: inherit;\n  text-align: left;\n  background: transparent;\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.25));\n  border-radius: 6px;\n  cursor: pointer;\n}\n\n.ccr-card-option:hover:not(:disabled) { background: var(--ccr-panel-highlight); }\n.ccr-card-option:disabled { opacity: 0.45; cursor: default; }\n.ccr-card-option__name { font-size: 12px; font-weight: 500; }\n.ccr-card-option__meta { font-size: 11px; opacity: 0.6; }\n\n.ccr-card {\n  margin-top: 6px;\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.25));\n  border-radius: 8px;\n  overflow: hidden;\n}\n\n.ccr-card__head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 10px;\n  font-size: 12px;\n}\n\n.ccr-card__name { font-weight: 500; }\n\n.ccr-card__meta {\n  font-size: 11px;\n  opacity: 0.5;\n  margin-right: auto;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  max-width: 40%;\n}\n\n.ccr-card__panel {\n  padding: 8px 10px 10px;\n  border-top: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.18));\n  font-size: 12px;\n}\n\n/* \u2550\u2550\u2550 \u6743\u9650\uFF08\u4E24\u4E2A\u65B9\u5411\u53EF\u5206\u522B\u8BBE\u7F6E\uFF09 \u2550\u2550\u2550 */\n.ccr-perm-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 6px;\n  min-width: 0;\n}\n\n.ccr-perm-row__who {\n  display: flex;\n  align-items: baseline;\n  gap: 5px;\n  min-width: 0;\n  flex: 1 1 auto;\n}\n\n.ccr-perm-row__name {\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  max-width: 42%;\n  font-size: 12px;\n}\n\n.ccr-perm-row__verb {\n  flex: none;\n  font-size: 13px;\n  line-height: 1;\n  opacity: 0.45;\n}\n\n.ccr-perm-row__target {\n  flex: 1 1 auto;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  max-width: 42%;\n  font-size: 12px;\n  opacity: 0.85;\n}\n\n.ccr-perm-row .ccr-seg { flex: none; }\n\n/* \u2550\u2550\u2550 \u5F85\u786E\u8BA4\u7684\u6743\u9650\u5347\u7EA7 \u2550\u2550\u2550 */\n.ccr-pending {\n  margin: 10px 0;\n  padding: 10px;\n  border: 1px solid var(--ccr-flow-color);\n  border-radius: 8px;\n  background: var(--ccr-panel-highlight);\n}\n\n.ccr-pending__text {\n  font-size: 12px;\n  line-height: 1.5;\n}\n\n/* \u2550\u2550\u2550 ConnectionPanel \u2550\u2550\u2550 */\n.ccr-panel {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  font-size: 13px;\n  min-width: 220px;\n}\n\n.ccr-panel__tabs {\n  display: flex;\n  gap: 4px;\n  padding: 8px;\n  border-bottom: 1px solid rgba(128, 128, 128, 0.2);\n}\n\n.ccr-panel__tab {\n  padding: 4px 12px;\n  border-radius: 4px;\n  cursor: pointer;\n  opacity: 0.6;\n  transition: opacity var(--ccr-fast);\n  user-select: none;\n}\n\n.ccr-panel__tab--active {\n  opacity: 1;\n  background: var(--ccr-panel-highlight);\n}\n\n.ccr-panel__list {\n  flex: 1;\n  overflow-y: auto;\n  padding: 4px 0;\n}\n\n.ccr-panel__empty,\n.ccr-panel__error {\n  padding: 12px;\n  opacity: 0.6;\n}\n\n.ccr-panel__error { color: #EF4444; opacity: 1; }\n\n.ccr-row {\n  padding: 8px 12px;\n  cursor: pointer;\n  transition: background var(--ccr-fast);\n  border-left: 2px solid transparent;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.ccr-row:hover { background: var(--ccr-panel-highlight); }\n.ccr-row--open { background: var(--ccr-panel-highlight); }\n\n.ccr-card-row {\n  padding: 4px 12px 4px 28px;\n  font-size: 12px;\n  opacity: 0.85;\n}\n\n.ccr-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  padding: 6px 12px 10px;\n}\n\n.ccr-actions button {\n  font-size: 11px;\n  padding: 3px 8px;\n  border-radius: 4px;\n  border: 1px solid rgba(128, 128, 128, 0.35);\n  background: transparent;\n  color: inherit;\n  cursor: pointer;\n}\n\n.ccr-actions button:hover:not(:disabled) { background: var(--ccr-panel-highlight); }\n.ccr-actions button:disabled { opacity: 0.45; cursor: default; }\n\n/* \u2550\u2550\u2550 \u65E0\u969C\u788D / \u964D\u4F4E\u52A8\u6548 \u2550\u2550\u2550 */\n@media (prefers-reduced-motion: reduce) {\n  .ccr-flow__band,\n  .ccr-rail__flow,\n  .ccr-anchor--dragging .ccr-anchor__pulse { animation: none !important; }\n  .ccr-flow__particle { display: none !important; }\n}\n";
/**
 * 把样式注入 document.head（幂等）。
 *
 * @returns 注销函数；非浏览器环境下返回空操作。
 */
export declare function injectStyles(): () => void;
